def ajustar_datos(apps, schema_editor):
    """
    Lo que ya existía, en las reglas nuevas:

    - Las versiones de parámetros quedan encadenadas por vigencia: la primera
      rige desde el 1 de enero de 2026 y cada una hasta el día antes de la
      siguiente (por el lunes de la semana en que se guardó).
    - El switch «Planner» queda encendido para quien ya tiene un plan
      relacionado y activo: así nadie sale de la medición con el cambio.
    - Los resultados ya calculados miden lo de su línea base.
    """
    Parametros = apps.get_model('planner', 'Parametros')
    PlanPlanner = apps.get_model('planner', 'PlanPlanner')
    ResultadoSemana = apps.get_model('planner', 'ResultadoSemana')
    User = apps.get_model('accounts', 'User')

    versiones = list(Parametros.objects.order_by('created_at', 'id'))
    for i, version in enumerate(versiones):
        if i == 0:
            version.vigente_desde = datetime.date(2026, 1, 1)
        else:
            creada = version.created_at.date()
            version.vigente_desde = creada - datetime.timedelta(days=creada.weekday())
        version.vigente_hasta = None
    for anterior, siguiente in zip(versiones, versiones[1:], strict=False):
        if siguiente.vigente_desde <= anterior.vigente_desde:
            siguiente.vigente_desde = anterior.vigente_desde + datetime.timedelta(days=7)
        anterior.vigente_hasta = siguiente.vigente_desde - datetime.timedelta(days=1)
    for version in versiones:
        version.save(update_fields=['vigente_desde', 'vigente_hasta'])

    con_plan = PlanPlanner.objects.filter(activo=True, colaborador__isnull=False).values(
        'colaborador_id'
    )
    User.objects.filter(pk__in=con_plan).update(medir_planner=True)

    for resultado in ResultadoSemana.objects.all():
        resultado.weekly_total = resultado.weekly_base
        resultado.save(update_fields=['weekly_total'])


